package service

import (
	"reflect"
	"runtime"
)

// unimplementedType is the name of the generated struct whose methods answer
// 501 for every operation. A provider embeds it.
const unimplementedType = "Unimplemented"

// autogenerated is the file the Go runtime reports for a method the compiler
// wrote: the wrapper that promotes an embedded type's method, or that gives a
// pointer the methods of its value.
const autogenerated = "<autogenerated>"

// method is what a handler's method turned out to be.
type method int

const (
	// unclassified is a method the check cannot place, so the service's
	// implemented operations are unknown.
	unclassified method = iota
	// declared is a method the handler's own code declares: an implemented
	// operation.
	declared
	// unimplemented is the generated Unimplemented's method, reached through
	// embedding: the operation answers 501.
	unimplemented
)

// Implemented returns the operations, out of operations, that handler declares
// itself rather than reaching through the generated Unimplemented it embeds. It
// returns ok false, and no operations, when handler is nil or when any of its
// methods cannot be classified, so a count is never a guess.
//
// It uses reflection, once per service when the capabilities are first asked
// for, never on a call. A method the compiler promoted from an embedded type is
// a wrapper whose file the runtime reports as "<autogenerated>"; the check
// follows such a wrapper down the embedded fields to the method it reaches, and
// counts the operation as unimplemented when that method is declared on a type
// named Unimplemented, as the generated one is. The
// tests of cmd/gostack pin the counts of the registered services, so a
// toolchain that reports wrappers differently fails them.
func Implemented(handler any, operations []string) (implemented []string, ok bool) {
	if handler == nil {
		return nil, false
	}

	t := reflect.TypeOf(handler)
	implemented = []string{}

	for _, operation := range operations {
		switch classify(t, operation) {
		case declared:
			implemented = append(implemented, operation)
		case unimplemented:
		default:
			return nil, false
		}
	}

	return implemented, true
}

// classify places the method name of t.
func classify(t reflect.Type, name string) method {
	m, found := t.MethodByName(name)
	if !found {
		return unclassified
	}

	fn := runtime.FuncForPC(m.Func.Pointer())
	if fn == nil {
		return unclassified
	}

	file, _ := fn.FileLine(fn.Entry())

	switch {
	case file == "":
		return unclassified
	case file != autogenerated && named(t) == unimplementedType:
		return unimplemented
	case file != autogenerated:
		return declared
	default:
		return promoted(t, name)
	}
}

// promoted places the method name of t that the compiler wrote: a pointer's
// method reached through its value, or a struct's method reached through the
// one embedded field that has it.
func promoted(t reflect.Type, name string) method {
	addressable := t.Kind() == reflect.Pointer
	if addressable {
		t = t.Elem()

		if _, found := t.MethodByName(name); found {
			return classify(t, name)
		}
	}

	if t.Kind() != reflect.Struct {
		return unclassified
	}

	var from reflect.Type

	for field := range t.Fields() {
		if !field.Anonymous {
			continue
		}

		fieldType := field.Type
		if addressable && fieldType.Kind() != reflect.Pointer {
			fieldType = reflect.PointerTo(fieldType)
		}

		if _, found := fieldType.MethodByName(name); !found {
			continue
		}

		// Two embedded fields with the method are settled by depth, which this
		// check does not work out.
		if from != nil {
			return unclassified
		}

		from = fieldType
	}

	if from == nil {
		return unclassified
	}

	return classify(from, name)
}

// named returns the name of t, or of what t points to.
func named(t reflect.Type) string {
	if t.Kind() == reflect.Pointer {
		t = t.Elem()
	}

	return t.Name()
}
